  busTable.innerHTML=buses.map((item,index)=>{const endpoint=busEndpoint(kind,item.endpoint_id)||{};return `<div class="resource-row bus-row"><div class="axis-row-head"><b>${escapeHtml(item.name||`${kind}_bus_${index}`)}</b><span class="endpoint-status planned">仅数字孪生</span><button data-remove-bus="${index}" data-kind="${kind}">移除</button></div><div class="resource-fields"><label>逻辑名称<input data-bus="${index}" data-kind="${kind}" data-bus-role="name" value="${escapeHtml(item.name||'')}" maxlength="32"></label><label class="endpoint-field">硬件端点<select data-bus="${index}" data-kind="${kind}" data-bus-role="endpoint_id">${busEndpointOptions(kind,item.endpoint_id)}</select></label>${contractFields('bus',kind,index,item,endpoint)}${flagFields('bus',kind,index,item,endpoint.flags||[])}<div class="constraint-note">${endpoint.controller||'未知端点'} · ${kind==='i2c'?`SCL ${endpoint.scl_pin||'—'} / SDA ${endpoint.sda_pin||'—'}`:`SCK ${endpoint.sck_pin||'—'} / MISO ${endpoint.miso_pin||'—'} / MOSI ${endpoint.mosi_pin||'—'}`}；端点来自板卡白名单，STM32 BSP 尚未验收。</div></div></div>`}).join('')||`<p class="muted">此板卡没有已选择的 ${title} 总线。</p>`;
